using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using MoneyWay.Application.Strategies.Nasdaq.MentorSessions;
using MoneyWay.Infrastructure.Strategies.Nasdaq;

namespace MoneyWay.IntegrationTests;

// Canonical results are generated by the existing multi-timeframe use case from explicitly synthetic fixture CSVs.
public sealed class NasdaqStandardDiagnosticAttemptTests : IDisposable
{
    private readonly NasdaqMentorSessionImportTests fixture = new();
    private readonly string root = Path.Combine(Path.GetTempPath(), "moneyway-standard-attempt-" + Guid.NewGuid().ToString("N"));
    private readonly NasdaqMentorSessionReplayReport canonical;
    private readonly NasdaqMentorSessionReplayInput replayInput;
    private readonly string reportPath;
    private readonly LocalNasdaqExecutionEvidenceStore store;
    private readonly NasdaqSupervisedSessionState session;
    public NasdaqStandardDiagnosticAttemptTests()
    {
        Directory.CreateDirectory(root); reportPath = Path.Combine(root, "synthetic-standard-canonical.json");
        var source = fixture.Input();
        // Rename the fixture's synthetic NASDAQ label to synthetic US100 throughout CSV identity only.
        // No authentic US100 acquisition or human market selections are implied; missing human inputs stay missing.
        var files = source.CsvFiles.ToDictionary(p => p.Key, p =>
        {
            var path = Path.Combine(root, Path.GetFileName(p.Value));
            File.WriteAllText(path, File.ReadAllText(p.Value).Replace(",NASDAQ,", ",US100,", StringComparison.Ordinal)); return path;
        });
        var input = replayInput = new("synthetic-us100-canonical-no-human-evidence",
            new(source.Session.StrategyId, source.Session.StrategyVersion, source.Session.ProviderId, new("US100"), source.Session.TradingDay), files, []);
        canonical = new RunLocalNasdaqMentorSessionUseCase().Execute(input);
        using (var stream = File.Create(reportPath)) NasdaqMentorSessionReportJson.Write(stream, canonical);
        store = new(Path.Combine(root, "capture"));
        session = store.OpenSession(Guid.NewGuid(), new("synthetic:standard-attempt", input.Session.TradingDay, input.Session.ProviderId.Value,
            input.Session.Symbol.Value, "Standard", "synthetic:operator", "note:synthetic Standard operational scope"));
    }
    private WebApplicationFactory<Program> App(string? path = null) => new WebApplicationFactory<Program>().WithWebHostBuilder(b => b.UseEnvironment("Development")
        .UseSetting("NasdaqHistoricalDemo:ReportPath", path ?? reportPath).UseSetting("NasdaqExecutionEvidence:Directory", Path.Combine(root, "capture")));
    private string Route => $"/api/nasdaq/supervised-sessions/{session.SessionKey}/diagnostic";
    private static async Task<HttpResponseMessage> Post(HttpClient client, string path, object body)
    {
        using var request = new HttpRequestMessage(HttpMethod.Post, path) { Content = JsonContent.Create(body) };
        request.Headers.Add("X-MoneyWay-Local-Capture", "1"); return await client.SendAsync(request);
    }
    private NasdaqSupervisedExecutionEvidenceDraft Draft(NasdaqCanonicalDiagnosticReference reference) => new(session.SessionId, session.Identity.TradingDay,
        "synthetic:manual platform", session.Identity.Symbol.Value, "synthetic:operator", "note:synthetic documentary observation", "synthetic initial")
    {
        SourceProviderId = session.Identity.ProviderId.Value,
        Scenario = "Standard",
        Direction = "Buy",
        CanonicalDiagnostic = reference,
        Entry = new("note:synthetic own entry", "ReportedExecution") { Symbol = session.Identity.Symbol.Value },
        Exit = new("note:synthetic closing observation", "ReportedClosure") { Symbol = session.Identity.Symbol.Value, TimePrecision = "Approximate", OriginalTime = "synthetic around close" },
        Association = "HumanReported",
        AssociationSourceReference = "note:synthetic explicit same trade"
    };
    [Fact]
    public async Task ActualCanonicalFrameAndRulesAreReturnedWithoutApprovalOrMutation()
    {
        using var app = App(); var http = app.CreateClient();
        var before = SHA256.HashData(File.ReadAllBytes(reportPath));
        var view = (await http.GetFromJsonAsync<NasdaqSupervisedDiagnosticContext>(Route))!;
        var at = view.Report.SelectedFrame!;
        var actual = canonical.Frames.Single(f => f.Strategy.Step == at.Step);
        Assert.Equal(actual.Strategy.AsOfUtc, at.AsOfUtc);
        Assert.Equal(canonical.Canonical!.Frames.Single(f => f.Step == at.Step).Verdict.ToString(), at.Verdict);
        Assert.Equal(actual.Strategy.Evaluations.Select(e => (e.RuleId.Value, e.Result.ToString(), e.Reason)), at.Rules.Select(r => (r.RuleId, r.Result, r.Reason)));
        Assert.Contains(at.Rules, r => r.IsRequired && r.Result == "Passed");
        Assert.Contains(at.Rules, r => r.Result is "Waiting" or "HumanValidationRequired" or "DataUnavailable");
        Assert.Contains(at.Rules, r => r.RuleId == "NQ-M1-001" && r.Result != "Passed");
        Assert.Contains(view.Dependencies, d => d.RuleId == "NQ-M1-001" && d.Prerequisites.Contains("NQ-M5-001"));
        Assert.Contains("1130", view.SpecificationConflict); Assert.Contains("1100", view.SpecificationConflict);
        Assert.Contains("CandidateVersion", view.CorrectionPath); Assert.Contains("NotGranted", view.Authorization);
        Assert.False(view.Session.Terminal); Assert.False(view.Session.BrokerExecutionVerified);
        Assert.Equal(before, SHA256.HashData(File.ReadAllBytes(reportPath)));
        var repeated = (await http.GetFromJsonAsync<NasdaqSupervisedDiagnosticContext>(Route))!;
        Assert.Equal(JsonSerializer.Serialize(view.Report), JsonSerializer.Serialize(repeated.Report));
    }
    [Fact]
    public async Task FrameBindingSurvivesRestartAndDocumentaryCorrectionsWithoutChangingCanonicalOutput()
    {
        NasdaqSupervisedDiagnosticContext diagnostic; NasdaqSupervisedExecutionEvidenceView record;
        using (var app = App())
        {
            var http = app.CreateClient(); diagnostic = (await http.GetFromJsonAsync<NasdaqSupervisedDiagnosticContext>(Route))!;
            var response = await Post(http, "/api/nasdaq/execution-evidence", new { submissionId = Guid.NewGuid(), evidence = Draft(diagnostic.Reference) });
            Assert.Equal(HttpStatusCode.Created, response.StatusCode); record = (await response.Content.ReadFromJsonAsync<NasdaqSupervisedExecutionEvidenceView>())!;
            Assert.False(store.Session(session.SessionKey).Terminal); Assert.Null(store.Session(session.SessionKey).ExecutionConfirmation);
        }
        using var restarted = App(); var client = restarted.CreateClient();
        var saved = await client.GetFromJsonAsync<NasdaqSupervisedExecutionEvidenceView>($"/api/nasdaq/execution-evidence/{record.Record.RecordId}");
        Assert.Equal(diagnostic.Reference, saved!.Record.Evidence.CanonicalDiagnostic);
        var selected = await client.GetFromJsonAsync<NasdaqSupervisedDiagnosticContext>(Route + $"?frameStep={diagnostic.Reference.FrameStep}&reportSha256={diagnostic.Reference.ReportSha256}");
        Assert.Equal(JsonSerializer.Serialize(diagnostic.Report.SelectedFrame), JsonSerializer.Serialize(selected!.Report.SelectedFrame));
        Assert.Null(selected.Report.SelectedSessionLastFrame);
        var revised = await Post(client, $"/api/nasdaq/execution-evidence/{record.Record.RecordId}/revisions", new { submissionId = Guid.NewGuid(), expectedRevision = record.RevisionHash, evidence = record.Record.Evidence with { RevisionReason = "synthetic correction" } });
        Assert.Equal(HttpStatusCode.OK, revised.StatusCode);
        Assert.Equal(diagnostic.Reference, (await revised.Content.ReadFromJsonAsync<NasdaqSupervisedExecutionEvidenceView>())!.Record.Evidence.CanonicalDiagnostic);
        Assert.Equal(record.RevisionHash, store.Get(record.Record.RecordId, 1).RevisionHash);
    }
    [Theory]
    [InlineData("?frameStep=0", HttpStatusCode.BadRequest)]
    [InlineData("?frameStep=999999", HttpStatusCode.NotFound)]
    [InlineData("?reportSha256=invalid", HttpStatusCode.BadRequest)]
    [InlineData("?reportSha256=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", HttpStatusCode.Conflict)]
    [InlineData("?path=C:/Windows/win.ini", HttpStatusCode.BadRequest)]
    [InlineData("?ready=true", HttpStatusCode.BadRequest)]
    public async Task InvalidCallerSelectionsCannotReadFilesOrDeclareApproval(string query, HttpStatusCode expected)
    {
        using var app = App(); Assert.Equal(expected, (await app.CreateClient().GetAsync(Route + query)).StatusCode);
    }
    [Theory]
    [InlineData("StrategyVersion", "other-version")]
    [InlineData("Symbol", "USTEC")]
    [InlineData("ProviderId", "different-provider")]
    public async Task ForeignIdentityCannotBeAssociated(string field, string value)
    {
        var json = JsonNode.Parse(File.ReadAllText(reportPath))!; json["Session"]![field]!["Value"] = value; File.WriteAllText(reportPath, json.ToJsonString());
        using var app = App(); Assert.Equal(HttpStatusCode.Conflict, (await app.CreateClient().GetAsync(Route)).StatusCode);
    }
    [Fact]
    public async Task ChangedOrMissingReportDoesNotSubstituteAnotherFrameButDocumentsRemainReadable()
    {
        using var app = App(); var http = app.CreateClient(); var d = (await http.GetFromJsonAsync<NasdaqSupervisedDiagnosticContext>(Route))!;
        var saved = store.Save(Guid.NewGuid(), Draft(d.Reference));
        File.AppendAllText(reportPath, " ");
        Assert.Equal(HttpStatusCode.Conflict, (await http.GetAsync(Route + $"?frameStep={d.Reference.FrameStep}&reportSha256={d.Reference.ReportSha256}")).StatusCode);
        File.Move(reportPath, reportPath + ".preserved");
        Assert.Equal(HttpStatusCode.NotFound, (await http.GetAsync(Route)).StatusCode);
        Assert.Equal(HttpStatusCode.OK, (await http.GetAsync($"/api/nasdaq/execution-evidence/{saved.Record.RecordId}")).StatusCode);
        var correction = await Post(http, $"/api/nasdaq/execution-evidence/{saved.Record.RecordId}/revisions", new { submissionId = Guid.NewGuid(), expectedRevision = saved.RevisionHash, evidence = saved.Record.Evidence with { RevisionReason = "synthetic annotation despite unavailable report" } });
        Assert.Equal(HttpStatusCode.OK, correction.StatusCode);
    }
    [Fact]
    public async Task ClientCannotInventFrameTimestampOrPassedFlagAndCannotChangeBindingThroughRevision()
    {
        using var app = App(); var http = app.CreateClient(); var d = (await http.GetFromJsonAsync<NasdaqSupervisedDiagnosticContext>(Route))!;
        var wrong = await Post(http, "/api/nasdaq/execution-evidence", new { submissionId = Guid.NewGuid(), evidence = Draft(d.Reference with { AsOfUtc = d.Reference.AsOfUtc.AddSeconds(1) }) });
        Assert.Equal(HttpStatusCode.Conflict, wrong.StatusCode);
        var spoof = JsonSerializer.SerializeToNode(new { submissionId = Guid.NewGuid(), evidence = Draft(d.Reference) }, new JsonSerializerOptions(JsonSerializerDefaults.Web))!;
        spoof["evidence"]!["canonicalDiagnostic"]!["passed"] = true;
        Assert.Equal(HttpStatusCode.BadRequest, (await Post(http, "/api/nasdaq/execution-evidence", spoof)).StatusCode);
        var record = store.Save(Guid.NewGuid(), Draft(d.Reference));
        Assert.Throws<NasdaqEvidenceConflictException>(() => store.Save(Guid.NewGuid(), record.Record.Evidence with { CanonicalDiagnostic = null }, record.Record.RecordId, record.RevisionHash));
        Assert.Throws<ArgumentException>(() => store.Save(Guid.NewGuid(), record.Record.Evidence with { OriginalSymbol = "USTEC" }, record.Record.RecordId, record.RevisionHash));
    }
    [Fact]
    public async Task TerminalGuardDominatesDiagnosticAttemptEvenWhenReportDisappearsAndDocumentaryReadsRemainAvailable()
    {
        using var app = App(); var http = app.CreateClient(); var d = (await http.GetFromJsonAsync<NasdaqSupervisedDiagnosticContext>(Route))!;
        var record = store.Save(Guid.NewGuid(), Draft(d.Reference)); var reference = new NasdaqSupervisedExecutionRecordReference(record.Record.RecordId, 1, record.RevisionHash);
        store.SessionAction(session.SessionKey, new(Guid.NewGuid(), "ConfirmExecution", "synthetic:operator", "note:synthetic own trade") { Execution = reference, MoneyWayOwnedExecutionConfirmed = true });
        store.SessionAction(session.SessionKey, new(Guid.NewGuid(), "ConfirmClosure", "synthetic:operator", "note:synthetic closing event") { Execution = reference, MoneyWayTradeClosedConfirmed = true, ClosureKind = "OtherEvidencedExit", Reason = "synthetic source-confirmed close" });
        var locked = await http.GetFromJsonAsync<NasdaqSupervisedDiagnosticContext>(Route); Assert.True(locked!.Session.Terminal);
        Assert.Equal(JsonSerializer.Serialize(d.Report.SelectedFrame), JsonSerializer.Serialize(locked.Report.SelectedFrame));
        File.Move(reportPath, reportPath + ".preserved");
        var attempt = new NasdaqSupervisedSessionCommand(Guid.NewGuid(), "EntryIntent", "synthetic:operator", "note:synthetic second entry") { SetupReference = "synthetic:new", CanonicalDiagnostic = d.Reference };
        var rejected = await Post(http, $"/api/nasdaq/supervised-sessions/{session.SessionKey}/actions", attempt);
        Assert.Equal(HttpStatusCode.Conflict, rejected.StatusCode); Assert.Contains("TerminalSession", await rejected.Content.ReadAsStringAsync());
        Assert.Equal(HttpStatusCode.OK, (await http.GetAsync($"/api/nasdaq/execution-evidence/{record.Record.RecordId}")).StatusCode);
    }
    [Fact]
    public async Task NonCanonicalFramesCannotBePresentedAsAComputedStrategyDecision()
    {
        var noDiagnostic = new NasdaqMentorSessionReplayReport(replayInput, canonical.Imports, [], null, canonical.Frames);
        using (var stream = File.Create(reportPath)) NasdaqMentorSessionReportJson.Write(stream, noDiagnostic);
        using var app = App(); Assert.Equal(HttpStatusCode.UnprocessableEntity, (await app.CreateClient().GetAsync(Route)).StatusCode);
    }
    [Fact]
    public async Task DifferentBogotaSessionDateCannotAdoptThisDiagnostic()
    {
        var next = store.OpenSession(Guid.NewGuid(), new("synthetic:another-date", session.Identity.TradingDay.AddDays(1), session.Identity.ProviderId.Value,
            session.Identity.Symbol.Value, "Standard", "synthetic:operator", "note:synthetic next date, no calendar claim"));
        using var app = App();
        Assert.Equal(HttpStatusCode.Conflict, (await app.CreateClient().GetAsync($"/api/nasdaq/supervised-sessions/{next.SessionKey}/diagnostic")).StatusCode);
    }
    private sealed class FrameClock(DateTimeOffset at) : TimeProvider { public override DateTimeOffset GetUtcNow() => at; }
    [Fact]
    public async Task UnadmittedNativeMt5ReceiptCannotBecomeCanonicalDiagnostics()
    {
        var receipt = Path.Combine(root, "synthetic-native-unadmitted.json");
        File.WriteAllText(receipt, "{\"native_server_time\":\"2026.11.18 16:30\",\"canonical_ready\":false,\"canonical_utc_conversion_authorized\":false}");
        using var app = App(receipt);
        Assert.Equal(HttpStatusCode.UnprocessableEntity, (await app.CreateClient().GetAsync(Route)).StatusCode);
        Assert.False(store.Session(session.SessionKey).Terminal);
    }
    [Fact]
    public async Task NewReadIntegrationRetainsDevelopmentAndLoopbackRestrictions()
    {
        using var app = App(); var http = app.CreateClient();
        using var request = new HttpRequestMessage(HttpMethod.Get, Route); request.Headers.Host = "untrusted.example";
        Assert.Equal(HttpStatusCode.Forbidden, (await http.SendAsync(request)).StatusCode);
        using var production = App().WithWebHostBuilder(b => b.UseEnvironment("Production"));
        Assert.Equal(HttpStatusCode.NotFound, (await production.CreateClient().GetAsync(Route)).StatusCode);
    }
    [Fact]
    public async Task ExistingNonAuthorizingEntryIntentRetainsVerifiedReferenceButNeverConfirmsExecution()
    {
        var at = canonical.Frames.Last().Strategy.AsOfUtc;
        var local = new LocalNasdaqExecutionEvidenceStore(Path.Combine(root, "synthetic-current-date-attempt"), new FrameClock(at));
        var opened = local.OpenSession(Guid.NewGuid(), new(session.SessionId, session.Identity.TradingDay, session.Identity.ProviderId.Value,
            session.Identity.Symbol.Value, "Standard", "synthetic:operator", "note:synthetic frozen frame-time test"));
        using var reader = new ReadNasdaqHistoricalReport();
        var context = await new ReadNasdaqSupervisedDiagnostic(local, reader, reportPath, null).ReadAsync(opened.SessionKey);
        var command = new NasdaqSupervisedSessionCommand(Guid.NewGuid(), "EntryIntent", "synthetic:operator", "note:synthetic supervised intent only")
        { SetupReference = "synthetic:local intent", CanonicalDiagnostic = context.Reference };
        var attempted = local.SessionAction(opened.SessionKey, command);
        Assert.Equal(context.Reference, attempted.Events.Last().Command.CanonicalDiagnostic);
        Assert.Null(attempted.ExecutionConfirmation); Assert.False(attempted.CompleteSupervisedTrade);
        Assert.Equal("NotEstablishedByOperationalWorkflow", attempted.StrategyAuthorization);
        Assert.Equal("NoTrade", context.Report.SelectedFrame!.Verdict); // storing intent cannot manufacture canonical permission
        Assert.Equal(context.Reference, new LocalNasdaqExecutionEvidenceStore(Path.Combine(root, "synthetic-current-date-attempt"), new FrameClock(at)).Session(opened.SessionKey).Events.Last().Command.CanonicalDiagnostic);
    }
    [Fact]
    public async Task ExtendingActualCanonicalReplayLeavesEarlierSelectedRulesAndVerdictIdentical()
    {
        var frames = canonical.Frames.Where(f => NasdaqSupervisedSessionPolicy.TradingDay(f.Strategy.AsOfUtc) == session.Identity.TradingDay).ToArray();
        var chosen = frames[frames.Length / 2].Strategy;
        var shorterFiles = replayInput.CsvFiles.ToDictionary(p => p.Key, p =>
        {
            var lines = File.ReadAllLines(p.Value);
            var path = Path.Combine(root, "prefix-" + Path.GetFileName(p.Value));
            File.WriteAllLines(path, lines.Take(1).Concat(lines.Skip(1).Where(line => DateTimeOffset.Parse(line.Split(',')[5], System.Globalization.CultureInfo.InvariantCulture) <= chosen.AsOfUtc)));
            return path;
        });
        var shorter = new RunLocalNasdaqMentorSessionUseCase().Execute(new("synthetic-shorter-prefix", replayInput.Session, shorterFiles, []));
        var shorterPath = Path.Combine(root, "shorter.json");
        using (var stream = File.Create(shorterPath)) NasdaqMentorSessionReportJson.Write(stream, shorter);
        using var reader = new ReadNasdaqHistoricalReport();
        var first = await new ReadNasdaqSupervisedDiagnostic(store, reader, shorterPath, null).ReadAsync(session.SessionKey, chosen.Step);
        var extended = await new ReadNasdaqSupervisedDiagnostic(store, reader, reportPath, null).ReadAsync(session.SessionKey, chosen.Step);
        Assert.Equal(JsonSerializer.Serialize(first.Report.SelectedFrame), JsonSerializer.Serialize(extended.Report.SelectedFrame));
        Assert.Null(extended.Report.SelectedSessionLastFrame);
    }
    [Fact]
    public async Task FocusedSyntheticCanonicalArtifactCanBeExportedForRealHttpAcceptance()
    {
        var destination = Environment.GetEnvironmentVariable("MONEYWAY_STANDARD_DIAGNOSTIC_SMOKE_EXPORT");
        if (string.IsNullOrWhiteSpace(destination)) return;
        Assert.True(Path.IsPathFullyQualified(destination)); Assert.False(File.Exists(destination));
        File.Copy(reportPath, destination, overwrite: false);
        using var reader = new ReadNasdaqHistoricalReport();
        var view = await reader.ExecuteAsync(destination, null);
        Assert.Equal("US100", view.Symbol); Assert.Equal("synthetic-us100-canonical-no-human-evidence", view.SessionId);
    }
    [LocalMentorSessionFact]
    public async Task AuthenticReplay2Wf2FrameIsNotRelabeledStandardAndOriginalHashRemainsUnchanged()
    {
        const string real = @"C:\MoneyWay\session\reports\2026-09-08\canonical-preentry-ed4a1539bef845fd84f5a68dcfc81cbe.json";
        const string hash = "48b5743e86ea3f061b9ae3c1f2c7280dcad4bf5272d7da7cf69c68f0d24dd3db";
        using var reader = new ReadNasdaqHistoricalReport(); var report = await reader.ExecuteAsync(real, hash);
        var realScope = store.OpenSession(Guid.NewGuid(), new("synthetic:own-not-mentor", report.TradingDay, report.ProviderId, report.Symbol, "Standard", "synthetic:operator", "note:synthetic scope for real WF2 rejection test"));
        var service = new ReadNasdaqSupervisedDiagnostic(store, reader, real, hash);
        await Assert.ThrowsAsync<NasdaqEvidenceConflictException>(() => service.ReadAsync(realScope.SessionKey));
        Assert.False(store.Session(realScope.SessionKey).Terminal);
        Assert.Equal(hash, Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(real))));
    }
    public void Dispose() { fixture.Dispose(); if (Directory.Exists(root)) Directory.Delete(root, true); }
}
